// The panel types and layout presets of MDATK's figure (src/core/panel_tables.inc, generated by
// tools/gen_panel_tables.py from mdatk/render/panels.py and layout.py).
#include <gtest/gtest.h>

#include <string>
#include <vector>

#include "mdbridge/core/panels.hpp"

namespace mdbridge {
namespace {

TEST(Panels, TypesInRegistrationOrder) {
    std::vector<std::string> names;
    for (const core::PanelType& t : core::panelTypes()) {
        names.emplace_back(t.name);
        EXPECT_FALSE(t.label.empty());
        EXPECT_FALSE(t.description.empty());
        EXPECT_LE(t.minSeries, t.maxSeries);
    }
    EXPECT_EQ(names, (std::vector<std::string>{"structure", "timeseries", "dual_axis", "heatmap", "contact_map",
                                               "sequence", "secondary"}));
    const core::PanelType* dual = core::findPanelType("dual_axis");
    ASSERT_NE(dual, nullptr);
    EXPECT_EQ(dual->label, "Dual-axis time series");
    EXPECT_EQ(dual->dataKind, "series");
    EXPECT_EQ(dual->minSeries, 2);
    EXPECT_EQ(dual->maxSeries, 2);
    EXPECT_EQ(core::findPanelType("contact_map")->dataKind, "pairmaps");
    EXPECT_EQ(core::findPanelType("structure")->maxSeries, 0);
    EXPECT_EQ(core::findPanelType("bogus"), nullptr);
}

TEST(Panels, LayoutPresets) {
    ASSERT_EQ(core::layoutPresets().size(), 16u);
    EXPECT_EQ(core::layoutPresets().front().name, "single");
    EXPECT_EQ(core::layoutPresets().back().name, "equal_4_strip");
    for (const core::LayoutPreset& p : core::layoutPresets()) {
        EXPECT_FALSE(p.slots.empty()) << p.name;
        EXPECT_TRUE(p.heightRatios.empty() || p.heightRatios.size() == static_cast<std::size_t>(p.rows)) << p.name;
        for (const core::LayoutSlot& s : p.slots) {
            EXPECT_TRUE(0 <= s.row0 && s.row0 < s.row1 && s.row1 <= p.rows) << p.name;
            EXPECT_TRUE(0 <= s.col0 && s.col0 < s.col1 && s.col1 <= p.cols) << p.name;
        }
    }
    const core::LayoutPreset* p = core::findLayoutPreset("large_plus_3");  // the default
    ASSERT_NE(p, nullptr);
    EXPECT_EQ(p->label, "1 large + 3 small (right)");
    EXPECT_EQ(p->rows, 3);
    EXPECT_EQ(p->cols, 3);
    ASSERT_EQ(p->slots.size(), 4u);
    EXPECT_EQ(p->slots[0].row1, 3);
    EXPECT_EQ(p->slots[0].col1, 2);
    EXPECT_TRUE(p->heightRatios.empty());
    const core::LayoutPreset* strip = core::findLayoutPreset("large_plus_3_strip");
    ASSERT_NE(strip, nullptr);
    EXPECT_EQ(std::vector<double>(strip->heightRatios.begin(), strip->heightRatios.end()),
              (std::vector<double>{1.0, 1.0, 1.0, 0.55}));
    EXPECT_EQ(strip->slots.back().col1, 3);
    EXPECT_EQ(core::findLayoutPreset("bogus"), nullptr);
}

}  // namespace
}  // namespace mdbridge
